create table public.messages (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  body text not null,
  created_at timestamptz not null default now()
);
alter table public.messages enable row level security;
create policy "owners read their messages"
  on public.messages for select
  using (auth.uid() = owner_id);
create policy "owners add messages"
  on public.messages for insert
  with check (auth.uid() = owner_id);
create policy "owners delete their messages"
  on public.messages for delete
  using (auth.uid() = owner_id);
create function public.get_messages_for_user(p_user_id uuid)
returns setof public.messages
language sql security definer set search_path = public as $$
  select * from public.messages where owner_id = p_user_id;
$$;
grant execute on function public.get_messages_for_user(uuid) to authenticated;
